# CP24 reconstructed targeted threshold-sensitivity analysis. This supplements
# the archived official event-count sensitivity and is kept clearly separate.
rm(list=ls());source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","reconstructed_panel_framework.R"));rp_install_and_load(c("dplyr","readr","tibble","purrr","tidyr"),"flowCore");source(file.path(sd_repo_root(),"R","panels","CP24","MANIFEST_RECONSTRUCTED.R"));a<-sd_analysis_dir("CP24");r<-file.path(a,"11_RData");out<-file.path(a,"12_threshold_sensitivity_RECONSTRUCTED");dir.create(out,recursive=TRUE,showWarnings=FALSE);load(file.path(r,"SDY2583_CP24_STEP2_feature_extraction_RECONSTRUCTED.RData"));load(file.path(r,"SDY2583_CP24_STEP3A_metadata_merge_age_QC_RECONSTRUCTED.RData"));metadata_for_merge<-metadata
main<-CP24_MANIFEST$thresholds;permissive<-main-0.2;stringent<-main+0.2;sets<-list(permissive=permissive,main=main,stringent=stringent);targets<-unique(c("pct_cd3_pos_total","pct_cd3_cd8_pos_total","pct_cd8_within_cd3","median_CD62L_in_CD3CD8","median_CD27_in_CD3CD8","pct_naive_like","pct_temra_like","pct_temra_cd27neg","pct_cd62lneg_cd27neg","pct_cd57_cx3cr1_cd95_pos","pct_pd1_pos",CP24_MANIFEST$integrated_score,names(CP24_MANIFEST$score_definitions)))
one_set<-function(label,thresholds){ft<-purrr::map_dfr(fcs_files,~extract_one(.x,thresholds));dat<-ft |> dplyr::left_join(metadata_for_merge,by="subject_id");scored<-rp_build_scores(dat,CP24_MANIFEST$score_definitions,CP24_MANIFEST$integrated_score);stats<-purrr::map_dfr(targets,~rp_fit_one(scored,.x,label,FALSE,CP24_MANIFEST$primary_event_col,0)) |> dplyr::mutate(targeted_fdr=p.adjust(p_value,"BH"),threshold_set=label);list(data=scored,statistics=stats)};results<-purrr::imap(sets,one_set);statistics_long<-dplyr::bind_rows(lapply(results,`[[`,"statistics"));summary_wide<-statistics_long |> dplyr::select(threshold_set,feature,beta_cancer_vs_healthy,p_value,targeted_fdr,direction) |> tidyr::pivot_wider(names_from=threshold_set,values_from=c(beta_cancer_vs_healthy,p_value,targeted_fdr,direction)) |> dplyr::mutate(direction_preserved=direction_main==direction_permissive&direction_main==direction_stringent,fdr_preserved=targeted_fdr_main<.05&targeted_fdr_permissive<.05&targeted_fdr_stringent<.05,robust_class=dplyr::case_when(direction_preserved&fdr_preserved~"direction_and_FDR_preserved",direction_preserved~"direction_preserved_FDR_not_preserved",TRUE~"direction_not_preserved"));threshold_sets<-purrr::imap_dfr(sets,~tibble::tibble(threshold_set=.y,marker=names(.x),threshold=as.numeric(.x)));readr::write_csv(threshold_sets,file.path(out,"SDY2583_CP24_threshold_sets_RECONSTRUCTED.csv"));readr::write_csv(statistics_long,file.path(out,"SDY2583_CP24_threshold_sensitivity_statistics_LONG_RECONSTRUCTED.csv"));readr::write_csv(summary_wide,file.path(out,"SDY2583_CP24_threshold_sensitivity_summary_WIDE_RECONSTRUCTED.csv"));save(results,statistics_long,summary_wide,targets,file=file.path(r,"SDY2583_CP24_STEP5_threshold_sensitivity_RECONSTRUCTED.RData"));print(table(summary_wide$robust_class))
